        printf("            Print help information\n\n");
        printf("    -l, --supported-language <SUPPORTED_LANGUAGE>\n");
        printf("            language to pull words from [default: english] [possible values: english, english1k,\n");
        printf("            english10k]\n\n");
        printf("    -p, --prompt <PROMPT>\n");
        printf("            custom prompt to use\n\n");
        printf("    -s, --number-of-secs <NUMBER_OF_SECS>\n");
        printf("            number of seconds to run test\n\n");
        printf("    -V, --version\n");
        printf("            Print version information\n\n");
        printf("    -w, --number-of-words <NUMBER_OF_WORDS>\n");
        printf("            number of words to use in test [default: 15]\n");
        return 0;
    }

    if (show_version) {
        printf("thokr 0.4.1\n");
        return 0;
    }

    /* If attempting to run a test or any non-help/version invocation and stdin is not a tty */
